#!/bin/sh
set -euo pipefail

SECRETS_FILE="${CI_WORKSPACE:-$(pwd)}/Loam/Config/Secrets.xcconfig"

if [ -z "${SUPABASE_URL:-}" ] || [ -z "${SUPABASE_ANON_KEY:-}" ]; then
  echo "warning: SUPABASE_URL and/or SUPABASE_ANON_KEY not set — using placeholder config (demo mode)."
  exit 0
fi

# xcconfig treats // as a comment; rewrite https://… as https:/$()/…
xcconfig_url="${SUPABASE_URL//:\/\//:\/\$()\/}"

cat > "$SECRETS_FILE" <<EOF
// Generated by ci_post_clone.sh from Xcode Cloud environment variables.
SUPABASE_URL = ${xcconfig_url}
SUPABASE_ANON_KEY = ${SUPABASE_ANON_KEY}
EOF

echo "Wrote ${SECRETS_FILE} from Xcode Cloud environment variables."
